//! Passive inert noscript imports acquire real target-owned Text and attributes.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture(parsed:bool)->(Document,Forms,Page){
 let mut d=crate::html::parse("<body><div id=mount></div><p id=out>Real</p>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-import.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);
 run(&mut d,&mut f,&mut p,r#"var inert=document.implementation.createHTMLDocument('source'),raw='\udfff\ud800<img id=fake src=missing><script>window.bad=1;</script>&amp;',source=inert.createElement('noscript'),mount=document.getElementById('mount'),watch=new MutationObserver(function(){});source.appendChild(inert.createTextNode(raw));watch.observe(mount,{childList:true});"#);
 if parsed{run(&mut d,&mut f,&mut p,"source.setAttribute('id','source');");}let Value::Host(source)=p.runtime.execute("source;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("actual source handle")};{let b=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state};assert_eq!(matches!(b.inert_import_source(source),Some(ImportSource::Parsed{..})),parsed);} (d,f,p)
}
#[test]
fn noscript_inert_import_created_and_parsed_deep_shallow_options_exact_owner_and_connection(){
 for parsed in [false,true]{let(mut d,mut f,mut p)=fixture(parsed);run(&mut d,&mut f,&mut p,r#"var old=source.firstChild,copy=document.importNode(source,true),shallow=document.importNode(source,false),options=document.importNode(source,{selfOnly:false});if(copy===source||copy===options||copy.ownerDocument!==document||copy.firstChild.ownerDocument!==document||source.ownerDocument!==inert||old.ownerDocument!==inert||copy.parentNode!==null||copy.firstChild===old||copy.firstChild.parentNode!==copy||copy.textContent!==raw||copy.firstChild.data!==raw||copy.innerHTML!==raw||options.firstChild.data!==raw||options.firstChild===copy.firstChild||shallow.ownerDocument!==document||shallow.childNodes.length||raw.charCodeAt(0)!==57343||raw.charCodeAt(1)!==55296||watch.takeRecords().length)throw 'actual imported owner and raw Text';if(source.hasAttribute('id')){var attr=source.getAttributeNode('id'),imported=copy.getAttributeNode('id');if(attr===imported||attr.ownerDocument!==inert||imported.ownerDocument!==document||imported.ownerElement!==copy||attr.ownerElement!==source||imported.value!=='source')throw 'actual imported Attr owner';}copy.id='copy';shallow.id='shallow';mount.appendChild(copy);mount.appendChild(shallow);var records=watch.takeRecords();if(records.length!==2||records[0].addedNodes[0]!==copy||records[1].addedNodes[0]!==shallow||document.getElementById('copy')!==copy||document.querySelectorAll('noscript').length!==2||document.getElementById('fake')!==null||document.querySelectorAll('script').length||window.bad!==undefined)throw 'passive imported connection';source.firstChild.data='Changed';source.setAttribute('data-source','Changed');if(copy.firstChild.data!==raw||options.firstChild.data!==raw||copy.hasAttribute('data-source')||old.data!=='Changed'||source.ownerDocument!==inert)throw 'independent imported storage';mount.removeChild(copy);if(copy.parentNode!==null||copy.firstChild.parentNode!==copy||copy.firstChild.data!==raw||watch.takeRecords()[0].removedNodes[0]!==copy)throw 'actual imported retirement';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());}
}
#[test]
fn noscript_inert_import_nontext_active_attribute_and_namespace_guards_remain_atomic(){
 for prepare in ["source.appendChild(inert.createElement('span'));","source.setAttribute('onclick','window.bad=2');","source.setAttribute('is','fake-widget');","source.setAttributeNS('urn:blocked','p:foreign','data');"]{let(mut d,mut f,mut p)=fixture(true);run(&mut d,&mut f,&mut p,prepare);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let error=p.runtime.execute("document.importNode(source,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("Import"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||source.ownerDocument!==inert||source.firstChild.data!==raw||window.bad!==undefined||document.getElementById('fake')!==null)throw 'protected import unchanged';document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());}
}
#[test]
fn noscript_inert_import_quota_refusals_publish_no_main_nodes_then_recover(){
 let(mut d,mut f,mut p)=fixture(true);p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let error=p.runtime.execute("document.importNode(source,true);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();let e=error.to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"{mode}: {error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.ownerDocument!==inert||source.firstChild.data!==raw||watch.takeRecords().length)throw 'import refusal atomic';");}
 p.begin_job();run(&mut d,&mut f,&mut p,"var copy=document.importNode(source,true);if(copy.ownerDocument!==document||copy.firstChild.ownerDocument!==document||copy.firstChild.data!==raw||copy.firstChild===source.firstChild||watch.takeRecords().length)throw 'fresh import recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
